import { PRODUCTS, findOption } from "@/config/catalog";
import { BASE_IMAGES, baseCoverage } from "@/config/baseImages";
import { PALETTE } from "@/config/palette";

/** Markdown list of which base photos exist and which are missing (docs/PREVIEW_IMAGES.md). */
export function previewCoverageMarkdown(): string {
  const rows = baseCoverage();
  const have = rows.filter((r) => r.baseId).length;
  const lines: string[] = [
    "# Preview base photos: what exists and what is missing",
    "",
    "<!-- Generated by `npm run previews:report` from src/config/baseImages.ts. Do not edit by hand. -->",
    "",
    `**${have} of ${rows.length}** product × stitch × material combinations have a light-cream base photo and fabric mask.`,
    "Each base photo is recoloured in the browser into every colour in src/config/palette.ts, so no per-colour",
    "photos are needed. Size is shown by the dimensions and the size diagram, never by enlarging the photo.",
    "",
    "| Product | Stitch | Material | Base photo | Supplied file |",
    "|---|---|---|---|---|",
  ];
  for (const r of rows) {
    const p = PRODUCTS[r.product];
    const b = BASE_IMAGES.find((x) => x.id === r.baseId);
    lines.push(
      `| ${p.name} | ${findOption(p.stitches, r.stitch)?.label} | ${findOption(p.materials, r.material)?.label} | ${
        r.baseId ? `\`${r.baseId}\`` : "**missing**"
      } | ${b?.sourceFile ?? ""} |`,
    );
  }
  lines.push("", "## Palette (representative screen colours, not verified supplier shades)", "");
  lines.push("| Colour | Hex | Texture strength | Note |", "|---|---|---|---|");
  for (const [id, c] of Object.entries(PALETTE)) {
    lines.push(`| ${c.label} (\`${id}\`) | ${c.hex} | ${c.texture} | ${"useBasePhoto" in c && c.useBasePhoto ? "shows the cream base photo unchanged" : ""} |`);
  }
  lines.push("");
  return lines.join("\n");
}
